请对以下 case 进行三维加权评分。

=== case_id ===
Case-26-group-buy-003

=== 用户原始指令 (query.txt) ===
给我做个咖啡拼单 口味可以勾选 数字看几个人了 点一下跳到app 快到点提醒我

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "给我做个咖啡拼单 口味可以勾选 数字看几个人了 点一下跳到app 快到点提醒我",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "hww://www.huawei.com/totemweather?enterType=share&cityCode="
      }
    }
  ],
  "dataModelSchema": {
    "group": {
      "title": {
        "type": "string",
        "description": "咖啡拼单标题",
        "sampleValue": "咖啡拼单"
      },
      "memberCountText": {
        "type": "string",
        "description": "当前已参与拼单人数展示文本",
        "sampleValue": "6人"
      },
      "memberGoalText": {
        "type": "string",
        "description": "拼单人数目标或差额提示",
        "sampleValue": "差2人满团"
      },
      "deadlineText": {
        "type": "string",
        "description": "拼单截止或提醒时间提示",
        "sampleValue": "18:00截单"
      }
    },
    "flavors": {
      "option1": {
        "name": {
          "type": "string",
          "description": "第一个咖啡口味名称",
          "sampleValue": "拿铁"
        },
        "value": {
          "type": "string",
          "description": "第一个咖啡口味选项值",
          "sampleValue": "latte"
        },
        "selected": {
          "type": "boolean",
          "description": "第一个咖啡口味是否已选",
          "sampleValue": true
        }
      },
      "option2": {
        "name": {
          "type": "string",
          "description": "第二个咖啡口味名称",
          "sampleValue": "美式"
        },
        "value": {
          "type": "string",
          "description": "第二个咖啡口味选项值",
          "sampleValue": "americano"
        },
        "selected": {
          "type": "boolean",
          "description": "第二个咖啡口味是否已选",
          "sampleValue": false
        }
      },
      "option3": {
        "name": {
          "type": "string",
          "description": "第三个咖啡口味名称",
          "sampleValue": "摩卡"
        },
        "value": {
          "type": "string",
          "description": "第三个咖啡口味选项值",
          "sampleValue": "mocha"
        },
        "selected": {
          "type": "boolean",
          "description": "第三个咖啡口味是否已选",
          "sampleValue": false
        }
      }
    },
    "reminder": {
      "title": {
        "type": "string",
        "description": "临近截止提醒标题",
        "sampleValue": "快到点"
      },
      "statusText": {
        "type": "string",
        "description": "距离提醒或截止的短文本",
        "sampleValue": "5分后"
      },
      "hint": {
        "type": "string",
        "description": "提醒开启状态提示",
        "sampleValue": "提醒已开"
      }
    },
    "actions": {
      "openLabel": {
        "type": "string",
        "description": "跳转到应用的按钮文案",
        "sampleValue": "进App"
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/person_3_fill.svg",
      "description": "三人组实心图标，适合表达咖啡拼单的多人参与状态。"
    }
  ]
}

